let pendingPracticeFen=null;let storageAvailable=true;let openings=[],page='today',search='',eco='all',savedOnly=false,catalogPage=0;
let chess=new Chess(),lesson=null,lessonType='opening',line=[],step=0,startFen=null,selected=null,legal=[],flipped=false,drill=false,drillSide='w',feedback='',feedbackError=false,free=false,lastMove=null;
