function save(){try{localStorage.setItem('knight-school-v1',JSON.stringify(progress))}catch{storageAvailable=false;toast('Browser storage is unavailable. Keep this tab open to retain progress.')}updateTop()}
function day(){const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}
function done(id){if(!progress.days.includes(day()))progress.days.push(day());progress.weak=progress.weak.filter(x=>x!==id);if(!progress.done.includes(id)){progress.done.push(id);if(!progress.days.includes(day()))progress.days.push(day());save();toast('Lesson completed. Nice work, Jake.')}else{save();toast('You’ve already completed this lesson. Repetition helps it stick.')}}
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),4200)}
function updateTop(){$('.top-stats').innerHTML='<span>✧</span> <b id="completedTop">'+progress.done.length+'</b> '+(progress.done.length===1?'lesson':'lessons')+' completed'}
function stopEngine(){engineToken++;if(engine)engine.terminate();engine=null;engineBusy=false;engineResult=null;engineError=''}
function resetContext(){pendingRecallResult=null;activeMistakeId=null;pausePlayback();stopEngine();compareNote='';selected=null;legal=[];feedback='';feedbackError=false;free=false;drill=false;playing=false;lastMove=null}
function movesFor(pgn,fen){const c=new Chess(fen||undefined);c.loadPgn((fen?`[SetUp "1"]\n[FEN "${fen}"]\n\n`:'')+pgn);return c.history()}
function loadLesson(item,type,initial=0){resetContext();lesson=item;lessonType=type;startFen=item.fen||null;line=movesFor(item.pgn||item.line,startFen);step=Math.min(initial,line.length);setPosition();}
function setPosition(){stopEngine();chess=new Chess(startFen||undefined);for(let i=0;i<step;i++)lastMove=chess.move(line[i]);if(step===0)lastMove=null;selected=null;legal=[];free=false}
function navigate(dest){location.hash=dest}
function renderNav(){ $('#nav').innerHTML=Object.entries(names).map(([id,name])=>`<a href="#${id}" class="${page===id?'active':''}"><span class="nav-icon">${icons[id]}</span>${name}${id==='openings'?'<span class="nav-count">3.8k</span>':''}</a>`).join('');$('#breadcrumb').innerHTML=`Training room <span>/</span> ${names[page]||'Today'}`;$('.sidebar').classList.remove('open');updateTop() }
function heading(label,title,sub,extra=''){return `<div class="page-heading"><div><p class="eyebrow">${label}</p><h1>${title}</h1><p>${sub}</p></div>${extra}</div>`}
function workspace(){return `<div class="workspace"><div class="board-panel"><div class="board-appearance"><span class="mini-label">STAUNTON · STUDY BOARD</span><label for="boardTheme" class="sr-only">Board theme</label><select id="boardTheme" aria-label="Board theme">${[['walnut','Walnut'],['tournament','Tournament'],['slate','Slate']].map(([v,n])=>`<option value="${v}" ${document.documentElement.dataset.boardTheme===v?'selected':''}>${n}</option>`).join('')}</select></div><div class="player-label"><strong id="opponentLabel"><span class="piece-mini">♚</span> Black pieces</strong><span id="turnBadge">White to move</span></div><div class="board-area"><div class="eval" aria-label="Position evaluation"><div class="eval-fill" id="evalFill"></div></div><div class="board-shell"><div id="board" class="board" role="group" aria-label="Interactive chessboard"></div></div></div><div class="board-controls"><div class="control-group"><button class="icon-button" data-action="flip" title="Flip board" aria-label="Flip board">⇅</button><button class="icon-button" data-action="reset" title="Restart position" aria-label="Restart position">↺</button></div><div class="control-group"><button class="icon-button" data-action="first" aria-label="First position">|‹</button><button class="icon-button" data-action="prev" aria-label="Previous move">‹</button><button class="icon-button" data-action="next" aria-label="Next move">›</button><button class="icon-button" data-action="last" aria-label="Final position">›|</button></div><span id="boardStatus" class="board-status"></span></div><div class="playback-bar"><button class="primary" data-action="autoplay" id="autoplayButton">▶ Play through</button><label for="playbackSpeed">Each move</label><select id="playbackSpeed"><option value="5">5 sec</option><option value="12" selected>12 sec</option><option value="20">20 sec</option><option value="30">30 sec</option></select><span id="playbackStatus">Pause any time to study or ask.</span></div></div><section class="lesson-panel" id="lessonPanel" aria-label="Lesson and coach"></section></div>`}
function today(){loadLesson(families[0],'opening',6);$('#main').innerHTML=heading('YOUR NEXT MOVE','Welcome back, Jake.','Build your understanding. One position at a time.',`<div class="date-tag">${new Date().toLocaleDateString(undefined,{month:'short',day:'numeric',year:'numeric'})}</div>`)+`<div class="stats"><div class="stat"><div class="stat-icon">♙</div><div><strong>${openings.length.toLocaleString()}</strong><small>Opening variations</small></div><span class="stat-desc">A whole world to explore</span></div><div class="stat"><div class="stat-icon">✓</div><div><strong>${progress.done.length}</strong><small>Lessons completed</small></div><span class="stat-desc">Your knowledge, growing</span></div><div class="stat"><div class="stat-icon">◷</div><div><strong>${progress.days.length}</strong><small>Days you’ve trained</small></div><span class="stat-desc">Keep showing up</span></div></div>${reviewQueueSummary()}<div class="section-heading"><h2>Your board. Your next breakthrough.</h2><span>OPENING SPOTLIGHT</span></div>`+workspace()+`<div class="bottom-grid"><a href="#openings" class="path-card"><span class="card-icon">♙</span><h3>Know the opening. Understand the plan.</h3><p>Explore major openings and thousands of variations.</p><small>Opening library <span>↗</span></small></a><a href="#strategy" class="path-card"><span class="card-icon">♞</span><h3>See what your opponent misses.</h3><p>Practice tactics, pawn structures, and positional ideas.</p><small>Strategy & tactics <span>↗</span></small></a><a href="#endgames" class="path-card"><span class="card-icon">♔</span><h3>Turn an advantage into a win.</h3><p>Learn mating patterns and essential endgame techniques.</p><small>Endgame training <span>↗</span></small></a></div><div class="quote">“Help your pieces so they can help you.”</div>`;renderBoard();renderPanel()}
function drawSquare(sq,p,r,f){let isDark=(r+f)%2===1;let isLegal=legal.some(m=>m.to===sq);let check=p?.type==='k'&&p.color===chess.turn()&&chess.isCheck();return `<button class="square ${isDark?'dark':''} ${selected===sq?'selected':''} ${isLegal?'legal':''} ${p?'occupied':''} ${lastMove&&(lastMove.from===sq||lastMove.to===sq)?'last':''} ${check?'check':''}" data-square="${sq}" aria-label="${sq}${p?' '+(p.color==='w'?'White':'Black')+' '+pieceNames[p.type]:', empty'}" ${p?.color===chess.turn()?'aria-pressed="'+(selected===sq)+'"':''}>${f===0?`<span class="coord rank">${sq[1]}</span>`:''}${r===7?`<span class="coord file">${sq[0]}</span>`:''}${p?pieceVisual(p,unicode[p.color+p.type]):''}</button>`}
function renderBoard(){if(!$('#board'))return;let html='';for(let r=0;r<8;r++)for(let f=0;f<8;f++){const sq=String.fromCharCode(97+(flipped?7-f:f))+(flipped?r+1:8-r);html+=drawSquare(sq,chess.get(sq),r,f)}$('#board').innerHTML=html;let status=chess.isCheckmate()?'Checkmate':chess.isStalemate()?'Stalemate — draw':chess.isDraw()?'Draw':`${chess.turn()==='w'?'White':'Black'} to move${chess.isCheck()?' · check':''}`;$('#turnBadge').textContent=status;$('#boardStatus').textContent=free?'Exploring a variation':drill?'Your move':`${step} / ${line.length} steps`;$('#opponentLabel').innerHTML=`<span class="piece-mini">${flipped?'♔':'♚'}</span> ${flipped?'White':'Black'} pieces`;document.querySelectorAll('[data-action="next"],[data-action="last"]').forEach(el=>el.disabled=drill||playing||step>=line.length);document.querySelectorAll('[data-action="first"],[data-action="prev"]').forEach(el=>el.disabled=playing||drill||(!free&&step===0));$('#evalFill').style.height=engineResult?`${Math.max(5,Math.min(95,50+engineResult.whiteScore*8))}%`:'50%';updatePlaybackControls()}
function moveList(){const initial=new Chess(startFen||undefined),blackFirst=initial.turn()==='b',n=initial.moveNumber();return `<div class="moves" aria-label="Move list">${line.map((m,i)=>{const black=(i+(blackFirst?1:0))%2===1,number=n+Math.floor((i+(blackFirst?1:0))/2);return `<button class="move-chip ${step===i+1?'current':''}" data-step="${i+1}" title="${black?'Black':'White'} move ${number}" ${drill?'disabled':''}>${number}${black?'…':'.'} ${esc(m)}</button>`}).join('')}</div>`}
function feedbackBox(){return feedback?`<div class="feedback ${feedbackError?'error':''}" role="status">${esc(feedback)}</div>`:''}
function generalNote(){if(drill)return `Practice the studied line as ${drillSide==='both'?'both sides':side(drillSide)}. Other legal moves may be playable; this is recall practice for the selected line.`;const e=explainMove(chess,lesson);if(lessonType==='master'){const keys=Object.keys(lesson.notes).map(Number).filter(k=>k<=step);return lesson.notes[Math.max(...keys)]||lesson.study?.why||lesson.theme}if(e.authored)return e.authored;if(e.move)return e.facts.join(' ');return lesson?.study?.why||'Use Play through to follow both players’ moves. Pause to inspect the purpose, plans, and alternatives.'}
function familyFor(name){return [...families].sort((a,b)=>b.key.length-a.key.length).find(f=>name.toLowerCase().includes(f.key.toLowerCase())&&!(f.key==='Modern'&&name.includes('Benoni')))||null}
function renderPanel(){
 if(!$('#lessonPanel'))return;
 let html='';const exercise=['strategy','endgame'].includes(lessonType),e=explainMove(chess,lesson),finished=step>=line.length&&line.length>0;
 if(page==='practice')html=practicePanel();
 else if(lessonType==='review')html=`<span class="pill">YOUR GAME · REVIEW</span><h2>${esc(reviewName)}</h2><p class="lesson-subtitle">Follow every move and ask about the position below.</p>${moveList()}<div class="coach-note"><div class="coach-label">WHAT CHANGED</div>${esc(generalNote())}</div>${engineBox()}<div class="button-row"><button class="primary" data-action="analyze">Analyze this position ↗</button><button class="secondary" data-action="reviewMove" ${!e.move?'disabled':''}>Review last move</button><button class="secondary" data-action="export">Export PGN</button></div>`;
 else if(exercise)html=`<span class="pill">${esc(lesson.tag)}</span><h2>${esc(lesson.name)}</h2><p class="lesson-copy">${esc(lesson.text)}</p><div class="idea"><strong>Your thinking process</strong>${esc(lesson.plan)}</div>${line.length>1?(drill?`<div class="progress-track"><div style="width:${step/line.length*100}%"></div></div>`:moveList()):''}${feedbackBox()}<div class="coach-note"><div class="coach-label">${drill?'RECALL PRACTICE':finished?'THE RESULT':'YOUR TASK'}</div>${esc(drill?'Continue the line. Use a hint if you need one.':finished?lesson.after:lesson.hint)}</div>${line.length>1&&!drill?practiceSideSelect():''}<div class="button-row"><button class="primary" data-action="exercise">${drill?'Restart drill':'Practice this technique →'}</button><button class="secondary" data-action="${drill?'hint':'solution'}">${drill?'Show a hint':'Show the line'}</button></div>${finished&&!drill?'<button class="secondary" style="margin-top:10px" data-action="complete">Mark lesson complete ✓</button>':''}<div style="margin-top:15px">${engineBox()}<div class="button-row"><button class="secondary" data-action="analyze">Check with Stockfish</button><button class="secondary" data-action="playPosition">Play from here ↗</button></div></div><p class="notice">The line illustrates the technique. Alternatives are possible; use the engine to compare them.</p>`;
 else if(lessonType==='master')html=`<span class="pill">MASTER GAME · ${lesson.year} · ${esc(lesson.result||'')}</span><h2>${esc(lesson.name)}</h2><p class="lesson-subtitle">${esc(lesson.players)}</p><p class="lesson-copy">${esc(lesson.theme)}</p>${moveList()}<div class="coach-note"><div class="coach-label">THE STORY AT THIS STAGE</div>${esc(generalNote())}</div>${engineBox()}<div class="button-row"><button class="primary" data-action="analyze">Analyze position</button><button class="secondary" data-action="reviewMove" ${!e.move?'disabled':''}>Review this move</button><button class="secondary" data-action="complete">Mark studied ✓</button></div><p class="notice">Play through advances one half-move at a time. Read the detailed explanation and both players’ plans below.</p>`;
 else {const fam=lesson.plan?lesson:familyFor(lesson.name);html=`<span class="pill">OPENING STUDY ${lesson.eco?'· '+esc(lesson.eco):'· CORE IDEAS'}</span><h2>${esc(lesson.name)}</h2><p class="lesson-subtitle">${esc(fam?.title||'Understand every move, for both sides.')}</p><p class="lesson-copy">${esc(fam?.description||'Follow the named variation and inspect each move. The guide combines opening notes where available with observable board changes for other moves.')}</p>${drill?`<div class="progress-track"><div style="width:${step/line.length*100}%"></div></div>`:moveList()}${feedbackBox()}<div class="coach-note"><div class="coach-label">${drill?'RECALL PRACTICE':'WHY THIS MOVE'}</div>${esc(generalNote())}</div>${!drill?practiceSideSelect():''}<div class="button-row"><button class="primary" data-action="drill">${drill?'Restart drill':'Practice this opening'} →</button><button class="secondary" data-action="${drill?'exitDrill':'saveOpening'}">${drill?'Exit drill':progress.saved.includes(lesson.id)?'Saved ✓':'Save opening'}</button>${drill?'<button class="secondary" data-action="hint">Hint</button>':''}</div>${fam?.trap?`<p class="notice"><b>Watch out:</b> ${esc(fam.trap)}</p>`:''}<div style="margin-top:14px">${engineBox()}<div class="button-row"><button class="secondary" data-action="analyze">Analyze with Stockfish</button><button class="secondary" data-action="playPosition">Play from here ↗</button></div></div>`}
 html+=recallResultMarkup()+mistakeStudyMarkup();$('#lessonPanel').innerHTML=html;renderLearningExtras();updatePlaybackControls();
}
function engineBox(){
 if(!engineBusy&&!engineResult&&!engineError)return '';
 if(engineError)return `<div class="engine-box">${esc(engineError)}</div>`;
 return `<div class="engine-box"><div class="engine-state"><span>STOCKFISH 19 · LITE</span><span>${engineBusy?'Thinking…':'Depth '+(engineResult?.depth||'?')}</span></div>${engineResult?`<div class="engine-score">${engineResult.mate!==null?'Mate '+engineResult.mate:(engineResult.whiteScore>=0?'+':'')+engineResult.whiteScore.toFixed(2)}</div>${engineResult.moveReview?`<p>${esc(engineResult.moveReview.summary)}</p>`:''}${(engineResult.lines||[]).map((l,i)=>`<div class="engine-line"><b>${i+1}.</b> ${esc(l.san.slice(0,8).join(' '))}<small>${l.mateWhite!==null?'Mate '+l.mateWhite:(l.scoreWhite>=0?'+':'')+l.scoreWhite?.toFixed(2)}</small></div>`).join('')}<div>${esc(engineResult.explain)}</div><small>White’s perspective. Short searches are estimates, not proof of a forced result.</small>`:'Calculating candidate moves on your device.'}</div>`
}
function catalog(){resetContext();lesson=null;let isOpen=page==='openings';$('#main').innerHTML=heading(isOpen?'THE OPENING LIBRARY':page==='strategy'?'THINK LIKE A CHESS PLAYER':'FINISH WITH CONFIDENCE',isOpen?'Every opening has a story.':page==='strategy'?'Find the idea behind the move.':'Make the advantage count.',isOpen?`${openings.length.toLocaleString()} named variations. Explore freely, then train the lines you want to remember.`:page==='strategy'?'Tactical patterns, positional plans, and a repeatable thinking process.':'Essential checkmates, king activity, pawn endings, and defensive awareness.')+`<div class="toolbar"><input id="search" class="search" placeholder="${isOpen?'Search Sicilian, London, Najdorf, B90…':'Search lessons…'}" aria-label="Search lessons" value="${esc(search)}">${isOpen?`<select id="ecoFilter" aria-label="Opening family"><option value="all">All opening families</option><option value="A">A · Flank & irregular</option><option value="B">B · Semi-open games</option><option value="C">C · Open games & French</option><option value="D">D · Closed games & Grünfeld</option><option value="E">E · Indian defenses & Catalan</option></select><button class="secondary" id="savedFilter">${savedOnly?'✓ Saved openings':'♡ Saved openings'}</button>`:''}<button class="secondary" data-action="glossary">Chess terms ↗</button></div><div class="section-heading"><span id="resultCount"></span><span>${isOpen?'SEARCH • STUDY • RECALL':'READ • TRY • UNDERSTAND'}</span></div><div class="catalog" id="catalog"></div><div id="pager" class="pager"></div>`;if(isOpen)$('#ecoFilter').value=eco;renderCatalogCards()}
function listData(){let list=page==='openings'?[...families,...openings]:page==='strategy'?strategies:endgames;let q=search.toLowerCase().trim();return list.filter(x=>(!q||(x.name+' '+(x.eco||'')+' '+(x.tag||'')).toLowerCase().includes(q))&&(page!=='openings'||eco==='all'||x.eco?.startsWith(eco))&&(!savedOnly||page!=='openings'||progress.saved.includes(x.id)))}
function renderCatalogCards(){const list=listData(),per=18,pages=Math.max(1,Math.ceil(list.length/per));catalogPage=Math.min(catalogPage,pages-1);$('#resultCount').textContent=`${list.length.toLocaleString()} ${page==='openings'?(list.length===1?'study':'studies'):(list.length===1?'lesson':'lessons')}${savedOnly&&page==='openings'?' saved':''}`;$('#catalog').innerHTML=list.slice(catalogPage*per,(catalogPage+1)*per).map(x=>`<article class="catalog-card"><div class="catalog-header"><span class="pill">${esc(x.eco||x.tag||(x.plan?'GUIDED OPENING':'OPENING'))}</span>${progress.done.includes(x.id)?'<span class="badge-success">✓ Studied</span>':progress.saved.includes(x.id)?'<span class="saved">♡ Saved</span>':''}</div><h3>${esc(x.name)}</h3>${x.plan?'<span class="guided-tag">Guided · move-by-move explanations</span>':''}${x.pgn||x.line?`<code>${esc((x.pgn||x.line).slice(0,116))}${(x.pgn||x.line).length>116?'…':''}</code>`:''}${x.title?`<p>${esc(x.title)}</p>`:''}<div class="button-row"><button class="secondary" data-open="${x.id}">${page==='openings'?'Study this opening':'Open lesson'} <span>↗</span></button></div></article>`).join('')||'<div class="empty">No matching studies. Try a broader search or turn off Saved openings.</div>';$('#pager').innerHTML=pages>1?`<button class="secondary" id="previousPage" ${catalogPage===0?'disabled':''}>← Previous</button><span>Page ${catalogPage+1} of ${pages}</span><button class="secondary" id="nextPage" ${catalogPage===pages-1?'disabled':''}>Next →</button>`:''}
function openStudy(id,initial=0){const pool=[...families,...openings,...strategies,...endgames,...masters];const item=pool.find(x=>x.id===id);if(!item)return;let type=masters.includes(item)?'master':strategies.includes(item)?'strategy':endgames.includes(item)?'endgame':'opening';loadLesson(item,type,initial);$('#main').innerHTML=`<button class="back" data-action="back">← Back to ${names[page].toLowerCase()}</button>`+heading(type==='opening'?'UNDERSTAND THE POSITION':type==='master'?'LEARN FROM THE BOARD':'YOUR NEXT LESSON',esc(item.name),type==='master'?esc(item.theme):'Take your time. Read the idea, then make it your own.')+workspace();renderBoard();renderPanel()}
function masterCatalog(){resetContext();$('#main').innerHTML=heading('CLASSIC GAMES, DEEPER UNDERSTANDING','Watch the game. Understand the decisions.',`${masters.length} famous games. Automatic playback, both players’ plans, key moments, and questions about any position.`)+`<div class="toolbar"><input class="search" id="masterSearch" placeholder="Search a player, game, year, or theme…" aria-label="Search master games"><span class="mini-label">Click a game, then Play through.</span></div><div class="catalog" id="masterCatalogCards">${masters.map(g=>`<article class="catalog-card master-card" data-master-search="${esc((g.name+' '+g.players+' '+g.year+' '+g.theme).toLowerCase())}"><span class="master-year">${g.year}</span><h3>${g.name}</h3><p>${esc(g.players)}</p><p>${esc(g.theme)}</p><div class="button-row"><button class="primary" data-open="${g.id}">Study this game ↗</button></div></article>`).join('')}</div><p class="notice">Historical moves are game records from PGN Mentor; explanations are original study commentary. Modern engine analysis may find improvements for either side. A recorded resignation is not necessarily checkmate.</p>`}
function review(){resetContext();lessonType='review';lesson={id:'review',name:'Your game'};line=[];step=0;startFen=null;chess=new Chess();$('#main').innerHTML=heading('LEARN FROM YOUR OWN MOVES','Every game has something to teach you.','Import a saved game, replay the moves, and check positions with Stockfish.')+`<section class="review-import"><h3>Bring your game to the board.</h3><p>Paste PGN move text from your chess app, or choose a .pgn file. You can also paste a FEN to study a single position.</p><textarea id="pgnInput" aria-label="PGN or FEN input" placeholder="1. e4 e5 2. Nf3 Nc6 3. Bc4 Bc5…"></textarea><div class="button-row"><button class="primary" id="importPgn">Load game or position →</button><label class="secondary" for="pgnFile">Choose PGN file</label><input type="file" id="pgnFile" accept=".pgn,.txt" hidden><button class="secondary" id="sampleGame">Load example game</button></div><div id="importError" class="notice" role="status"></div></section>`+workspace();renderBoard();renderPanel()}
function importText(text){try{const candidate=new Chess();let fen=false;if(text.trim().split(/\s+/)[0]?.includes('/')&&!text.includes('[FEN')){candidate.load(text.trim());fen=true}else candidate.loadPgn(text.trim());if(!fen&&!candidate.history().length)throw new Error('No moves found.');const headers=candidate.getHeaders();const hist=candidate.history({verbose:true});resetContext();lessonType='review';lesson={id:'review'};reviewName=fen?'Your imported position':headers.White&&headers.Black&&headers.White!=='?'&&headers.Black!=='?'?headers.White+' vs. '+headers.Black:'Your imported game';line=candidate.history();startFen=fen?candidate.fen():hist[0]?.before||null;step=0;setPosition();$('#importError').textContent=fen?'Position loaded.':`${line.length} moves loaded. Use the board arrows to replay the game.`;renderBoard();renderPanel()}catch(e){$('#importError').textContent='Could not read that game or position. Check the PGN/FEN and try again. '+e.message}}
function practice(){resetContext();activeMistakeId=pendingMistakeId;pendingMistakeId=null;lesson=null;lessonType='practice';startFen=pendingPracticeFen;pendingPracticeFen=null;chess=new Chess(startFen||undefined);line=[];step=0;$('#main').innerHTML=heading('THE PRACTICE BOARD','Try an idea. Play it out.','Play both sides, test a position, or practice against Stockfish.')+workspace();renderBoard();renderPanel()}
function practicePanel(){let status=chess.isCheckmate()?`Checkmate. ${chess.turn()==='w'?'Black':'White'} wins.`:chess.isDraw()?'The game is drawn.':playing?`You are playing ${playSide==='w'?'White':'Black'}. ${chess.turn()===playSide?'Your move.':'Stockfish is thinking.'}`:'Move either side. Select a piece, then a highlighted destination.';return `<span class="pill">FREE PRACTICE</span><h2>Make the board your laboratory.</h2><p class="lesson-copy">${status}</p><div class="study-options"><label for="playSide">Play as</label><select id="playSide" ${playing?'disabled':''}><option value="w" ${playSide==='w'?'selected':''}>White</option><option value="b" ${playSide==='b'?'selected':''}>Black</option></select><label for="playLevel">Engine</label><select id="playLevel" ${playing?'disabled':''}><option value="0" ${playLevel==='0'?'selected':''}>Gentler</option><option value="5" ${playLevel==='5'?'selected':''}>Balanced</option><option value="15" ${playLevel==='15'?'selected':''}>Challenging</option></select></div><div class="button-row"><button class="primary" data-action="play">${playing?'Stop playing engine':'Play against Stockfish →'}</button><button class="secondary" data-action="undo">Undo move</button></div><div class="coach-note" style="margin-top:18px"><div class="coach-label">A GOOD HABIT</div>Before moving: check your opponent’s threats, look for checks and captures, and make sure your chosen piece will be safe.</div>${feedbackBox()}${engineBox()}<div class="button-row"><button class="secondary" data-action="analyze" ${playing?'disabled':''}>Analyze position</button><button class="secondary" data-action="export">Export PGN</button></div><div class="review-import" style="padding:13px;margin-top:18px"><label for="fenInput" class="mini-label">Study a specific position (FEN)</label><input id="fenInput" class="search" style="width:100%;margin:9px 0" placeholder="Paste FEN position…"><button class="secondary" data-action="loadFen">Load position</button></div><p class="notice">Engine levels adjust Stockfish’s skill setting; they are not calibrated Elo ratings. Even Gentler can be a difficult opponent.</p>`}
async function squareClick(sq){if(playing&&chess.turn()!==playSide)return;if(engineBusy&&playing)return;if(chess.isGameOver())return;const p=chess.get(sq);if(selected&&legal.some(m=>m.to===sq)){const candidates=legal.filter(m=>m.to===sq);let promotion='q';if(candidates.some(m=>m.promotion)){promotion=await choosePromotion();if(!promotion)return}attemptMove({from:selected,to:sq,promotion});return}if(p&&p.color===chess.turn()){selected=sq;legal=chess.moves({square:sq,verbose:true});renderBoard()}else{selected=null;legal=[];renderBoard()}}
function choosePromotion(){return new Promise(resolve=>{modal(`<h2>Choose your promotion</h2><p>Your pawn has reached the last rank.</p><div class="promotion">${['q','r','b','n'].map(t=>`<button data-promote="${t}" aria-label="Promote to ${pieceNames[t]}">${pieceVisual({color:chess.turn(),type:t})}</button>`).join('')}</div>`);$('#modal').onclose=()=>resolve(null);document.querySelectorAll('[data-promote]').forEach(el=>el.onclick=()=>{const p=el.dataset.promote;$('#modal').onclose=null;$('#modal').close();resolve(p)})})}
function attemptMove(move){
 pausePlayback();let m;try{m=chess.move(move)}catch{return}selected=null;legal=[];
 if(drill){progress.attempts++;if(m.san!==line[step]){drillErrors++;chess.undo();if(!progress.weak.includes(lesson.id))progress.weak.push(lesson.id);save();feedbackError=true;feedback='That is a legal move, but this drill recalls a specific studied line. Use the hint or explore your alternative outside the drill.';renderBoard();renderPanel();return}
  progress.correct++;save();lastMove=m;step++;feedbackError=false;const replies=[];if(drillSide!=='both')while(step<line.length&&chess.turn()!==drillSide){lastMove=chess.move(line[step]);replies.push(lastMove.san);step++}feedback=`Correct: ${m.san}.${replies.length?' The studied reply is '+replies.join(', ')+'.':''} Read the explanation below.`;
  if(step>=line.length){drill=false;if(lessonType==='opening')finishRecall();done(lesson.id);feedback='You recalled the full line. Study the result and try the other side next.'}renderBoard();renderPanel();return;
 }
 stopEngine();lastMove=m;free=true;feedback='';checkNotebookMove(m);renderBoard();renderPanel();if(playing&&!chess.isGameOver())analyze('play');
}
function autoReply(){if(drillSide!=='both')while(step<line.length&&chess.turn()!==drillSide){lastMove=chess.move(line[step]);step++}}
function showHint(){if(drill)drillHints++;const c=new Chess(chess.fen());try{const m=c.move(line[step]);document.querySelector(`[data-square="${m.from}"]`)?.classList.add('hint');feedback='Hint: move the '+pieceNames[m.piece]+' from '+m.from+'.';feedbackError=false;renderPanel()}catch{toast('Return to the lesson position first.')}}
function startDrill(){drillErrors=0;drillHints=0;pendingRecallResult=null;drillSide=$('#drillSide')?.value||drillSide;step=0;setPosition();drill=true;autoReply();feedback=step>=line.length?'This short line has no move for that side. Choose White or Both sides to practice it.':'Recall the studied variation. Select a piece to see its legal moves.';if(step>=line.length)drill=false;feedbackError=false;renderBoard();renderPanel()}
function modal(html){pausePlayback();$('#modalContent').innerHTML=html;$('#modal').showModal()}
function glossaryModal(){modal(`<p class="eyebrow">THE LANGUAGE OF CHESS</p><h2>Chess terms, in plain English.</h2>${Object.entries(glossary).map(([k,v])=>`<p><b>${esc(k==='pawnBreak'?'Pawn break':k)}</b><br>${esc(v)}</p>`).join('')}`)}
function about(){modal(`<p class="eyebrow">ABOUT KNIGHT SCHOOL</p><h2>Your personal study room.</h2><p>This version combines 3,865 named opening variations, 40 guided opening lines, advanced study chapters, sixteen historical games with playback, and local engine analysis. It is an expandable trainer, not an exhaustive encyclopedia of every grandmaster idea.</p><p><b>Your data:</b> saved openings, completed lessons, and training days stay in this browser. Clearing browser storage removes them. PGN imports and Stockfish analysis run on your device. Coaching runs locally with Stockfish and programmed rules. Ask ChatGPT previews a prompt, lets you copy it, and opens ChatGPT only when you choose; you decide when to paste and send it. No API key or separate API credits are required.</p><p><b>Open-source foundations</b></p><ul><li><a href="https://github.com/lichess-org/chess-openings" target="_blank" rel="noopener">Lichess chess-openings</a> — opening names and sequences (CC0). Guided notes cover major families; guided main lines have authored notes; other moves have board observations and family plans where available.</li><li><a href="https://github.com/jhlywa/chess.js" target="_blank" rel="noopener">chess.js 1.4.0</a> — legal move validation, PGN, and game rules. <a href="vendor/CHESS-LICENSE.txt">BSD license</a>.</li><li><a href="https://github.com/nmrugg/stockfish.js" target="_blank" rel="noopener">Stockfish.js 19.0.1</a>, lite single-threaded build — engine analysis. <a href="vendor/STOCKFISH-LICENSE.txt">GPLv3 license</a>. <a href="vendor/stockfish-source.tar.gz">Corresponding source</a>. Stockfish is a separate worker; limited search time and the lite model affect analysis.</li></ul><p>Lesson explanations are written for this trainer. Free coaching uses programmed rules and limited-time engine results. Ask ChatGPT opens an external conversation; it is not embedded in this website. Game scores come from PGN Mentor; annotations are original.</p><button class="secondary" data-action="exportProgress">Export your training progress</button>`) }
function progressModal(){
 const due=dueReviews(training),reviews=Object.values(training.reviews),recallRate=progress.attempts?Math.round(progress.correct/progress.attempts*100):0;
 modal(`<p class="eyebrow">YOUR TRAINING RECORD</p><h2>Keep what you learn.</h2><div class="training-stats"><div><strong>${progress.done.length}</strong><span>Lessons completed</span></div><div><strong>${due.length}</strong><span>Opening reviews due</span></div><div><strong>${recallRate}%</strong><span>Recall moves correct</span></div><div><strong>${training.mistakes.length}</strong><span>Saved mistakes</span></div></div><div class="plan-list"><div class="plan-item">Saved openings <span>${progress.saved.length}</span></div><div class="plan-item">Training days <span>${progress.days.length}</span></div><div class="plan-item">Lessons to revisit <span>${progress.weak.length}</span></div><div class="plan-item">Correct recall moves <span>${progress.correct} / ${progress.attempts}</span></div><div class="plan-item">Completed opening sessions <span>${training.sessions.length}</span></div></div><section class="training-section"><h3>Spaced opening practice</h3><p>Finish a recall drill to schedule that line for the side you practiced. Again returns in 10 minutes; successful recall increases the interval. You can adjust the result after each round.</p>${due.length?due.slice(0,12).map(r=>`<button class="queue-item" data-due-review="${esc(reviewKey(r.lessonId,r.side))}"><span>${esc(studyName(r.lessonId))}<small>${sideName(r.side)} · due ${dateLabel(r.due)}</small></span><b>Practice →</b></button>`).join(''):`<p>${reviews.length?'Nothing overdue. Next review: '+dateLabel(reviews.slice().sort((a,b)=>Date.parse(a.due)-Date.parse(b.due))[0].due):'No opening reviews scheduled yet. Complete your first opening drill.'}</p>`}<div class="button-row"><button class="secondary" id="reviewSaved">Review saved openings →</button>${progress.weak.length?'<button class="secondary" id="reviewWeak">Practice a weak spot ↗</button>':''}</div></section><section class="training-section"><h3>Mistake notebook</h3><p>Review a move with Stockfish to save inaccuracies, mistakes, blunders and missed mating lines. Return to the earlier position and try the better candidate.</p>${training.mistakes.slice(0,15).map(m=>`<button class="queue-item" data-mistake-study="${esc(m.id)}"><span>${esc(m.played)} · ${esc(m.grade)}<small>${side(m.mover)} · ${esc(m.bestMove)} was the earlier candidate · ${m.reviewCount||0} successful recalls</small></span><b>Review →</b></button>`).join('')||'<p>No engine-reviewed mistakes saved yet.</p>'}</section><section class="training-section"><h3>Backup & restore</h3><p>Back up progress, opening schedules, mistakes, Coach history, board theme and your saved ChatGPT destination. Keep a backup before changing devices or adding the home-screen app.</p><div class="button-row"><button class="primary" data-action="exportProgress">Download complete backup</button><button class="secondary" id="restoreProgress">Restore a backup</button></div><p class="notice">Backups stay on your device. No account, paid service, or cloud upload is needed.</p></section>`);
 if($('#reviewWeak'))$('#reviewWeak').onclick=()=>{const id=progress.weak[0];$('#modal').close();page=strategies.some(x=>x.id===id)?'strategy':endgames.some(x=>x.id===id)?'endgames':'openings';history.replaceState(null,'','#'+page);renderNav();openStudy(id)};
 $('#reviewSaved').onclick=()=>{savedOnly=true;search='';eco='all';$('#modal').close();if(page==='openings')catalog();else navigate('openings')};
 $('#restoreProgress').onclick=showRestore;
}
function download(name,text,type='text/plain'){const url=URL.createObjectURL(new Blob([text],{type}));let a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function engineExplanation(fen,uci){try{const c=new Chess(fen);const m=c.move({from:uci.slice(0,2),to:uci.slice(2,4),promotion:uci[4]||'q'});let out=`Candidate: ${m.san}. `;if(m.san.includes('#'))return out+'This is checkmate.';if(m.san.includes('+'))out+='It gives check, forcing a response. ';if(m.captured)out+='It captures a '+pieceNames[m.captured]+'. ';if(m.flags.includes('k')||m.flags.includes('q'))out+='It castles and brings the rook into play. ';if(!m.captured&&!m.san.includes('+'))out+=`The ${pieceNames[m.piece]} moves from ${m.from} to ${m.to}. `;return out+'Play through the suggested continuation and compare the resulting position.'}catch{return 'Examine the suggested continuation before choosing your move.'}}
async function analyze(mode='analyze'){
 pausePlayback();const fen=chess.fen();if(chess.isGameOver()){toast('This position is already finished.');return}
 stopEngine();const token=engineToken;engineBusy=true;const task=searchPosition(fen,{time:mode==='play'?650:analysisTime,multipv:mode==='play'?1:3,skill:mode==='play'?Number(playLevel):null});engine=task;renderPanel();
 try{const result=await task.promise;if(token!==engineToken||chess.fen()!==fen)return;engineBusy=false;engine=null;if(mode==='play'){lastMove=chess.move({from:result.bestMove.slice(0,2),to:result.bestMove.slice(2,4),promotion:result.bestMove[4]||'q'});free=true;renderBoard();renderPanel();return}setEngineResult(result);renderBoard();renderPanel()}
 catch(error){if(error.name==='AbortError'||token!==engineToken)return;engineBusy=false;engineError=error.message;if(mode==='play')playing=false;renderPanel()}
}
function legacyAction(action){if(action==='playPosition'){pendingPracticeFen=chess.fen();playSide=chess.turn();navigate('practice');return}if(action==='flip'){flipped=!flipped;renderBoard();return}if(action==='glossary'){glossaryModal();return}if(action==='back'){catalogOrPage();return}if(action==='analyze'){analyze();return}if(action==='export'){download('knight-school-game.pgn',chess.pgn());return}if(action==='exportProgress'){exportFullBackup();return}if(action==='play'){if(playing){stopEngine();playing=false;renderPanel();return}playSide=$('#playSide').value;playLevel=$('#playLevel').value;playing=true;stopEngine();renderPanel();if(chess.turn()!==playSide)analyze('play');return}if(action==='undo'){stopEngine();if(playing){chess.undo();if(chess.turn()!==playSide)chess.undo()}else chess.undo();lastMove=chess.history({verbose:true}).at(-1);selected=null;legal=[];renderBoard();renderPanel();if(playing&&!chess.isGameOver()&&chess.turn()!==playSide)analyze('play');return}if(action==='loadFen'){try{const c=new Chess($('#fenInput').value.trim());resetContext();chess=c;startFen=c.fen();renderBoard();renderPanel();toast('Position loaded.')}catch{toast('That FEN could not be read. Check that both kings are present.')}return}if(action==='saveOpening'){if(progress.saved.includes(lesson.id)){progress.saved=progress.saved.filter(x=>x!==lesson.id);toast('Opening removed from saved studies.')}else{progress.saved.push(lesson.id);toast('Opening saved for your next session.')}save();renderPanel();return}if(action==='drill'){startDrill();return}if(action==='exitDrill'){drill=false;step=0;feedback='';setPosition();renderBoard();renderPanel();return}if(action==='complete'){done(lesson.id);return}if(action==='exercise'||action==='retry'){step=0;setPosition();drill=true;feedback='Find the move that demonstrates this lesson.';feedbackError=false;renderBoard();renderPanel();return}if(action==='solution'){step=line.length;setPosition();drill=false;feedback='Demonstration revealed. Try it yourself next time to check your recall.';feedbackError=false;renderBoard();renderPanel();return}if(['first','prev','next','last','reset'].includes(action)){if(page==='practice'){if(action==='reset'){resetContext();chess=new Chess(startFen||undefined);line=[];step=0}else if(action==='first'){while(chess.undo()){}lastMove=null;free=false}else if(action==='prev'){chess.undo();lastMove=chess.history({verbose:true}).at(-1)}renderBoard();renderPanel();return}drill=false;feedback='';step=action==='first'||action==='reset'?0:action==='last'?line.length:action==='prev'?Math.max(0,step-1):Math.min(line.length,step+1);setPosition();renderBoard();renderPanel()}}

/* Clear entry points for the existing teaching and coaching features. */
function guidedCatalog(){
 resetContext();
 const studies=families.filter(x=>x.plan&&x.id).slice();
 $('#main').innerHTML=heading('GUIDED LESSONS','Learn the why behind every move.',studies.length+' guided opening studies · explanations for both sides · interactive chessboard')+
 '<p class="lesson-copy">Choose a guided line below. The original Openings menu still contains the complete reference library.</p>'+
 '<div class="catalog">'+studies.map(x=>'<article class="catalog-card"><span class="pill">GUIDED OPENING</span><h3>'+esc(x.name)+'</h3><p>'+esc(x.title||x.plan||'Move-by-move coaching')+'</p><button class="secondary" data-open="'+esc(x.id)+'">Study this opening →</button></article>').join('')+'</div>';
}
function analysisLanding(){
 resetContext();
 $('#main').innerHTML=heading('GAME ANALYSIS','Understand your moves.','Import a game, step through the moves and review positions with Stockfish.')+
 '<div class="catalog"><article class="catalog-card"><h3>Analyze a PGN game</h3><p>Import a game from Chess.com or Lichess, then use Review last move to estimate move quality and explain threats.</p><a class="secondary" href="#review">Open game review →</a></article><article class="catalog-card"><h3>Analyze your own moves</h3><p>Play through a position and use the Coach and Stockfish tools.</p><a class="secondary" href="#practice">Open free practice →</a></article></div>';
}
function mistakeLanding(){
 resetContext();
 $('#main').innerHTML=heading('MISTAKE NOTEBOOK','Learn from the moves you missed.',training.mistakes.length+' saved positions · revisit the original board and try a better move')+
 '<p class="lesson-copy">Mistakes are saved after you use Stockfish move review. If the list is empty, analyze a game first.</p>'+
 '<div class="catalog">'+(training.mistakes.length?training.mistakes.map(m=>'<article class="catalog-card"><span class="pill">'+esc(m.grade)+'</span><h3>'+esc(m.played)+'</h3><p>Candidate: '+esc(m.bestMove)+' · '+(m.reviewCount||0)+' successful recalls</p><button class="secondary" data-mistake-study="'+esc(m.id)+'">Retry this move →</button></article>').join(''):'<article class="catalog-card"><h3>No mistakes saved yet</h3><p>Start a game review, review your last move with Stockfish, then come back here.</p><a class="secondary" href="#review">Analyze a game →</a></article>')+'</div>';
}
function videoAcademy(){
 resetContext();
 const topics=[
 ['Start here','Chess basics and beginner lessons','https://lichess.org/video?q=beginner','Get comfortable with chess rules, development and common mistakes.'],
 ['Opening principles','Center control and piece development','https://lichess.org/video?tags=beginner%2Fopening','Learn why opening moves work before memorizing variations.'],
 ['Tactics','Forks, pins and missed captures','https://lichess.org/video?tags=beginner%2Ftactic','Spot concrete threats and prevent blunders.'],
 ['Strategy','Make a plan in the middlegame','https://lichess.org/video?tags=beginner%2Fstrategy','Learn piece activity, weak squares and planning.'],
 ['Endgames','Winning the positions that matter','https://lichess.org/video?tags=beginner%2Fendgame','Practice king activity, pawn endings and basic checkmates.'],
 ['Sicilian Defense','Understand Black’s ...c5 ideas','https://lichess.org/video?q=Sicilian','Connect opening videos with your Sicilian lessons.']
 ];
 $('#main').innerHTML=heading('VIDEO ACADEMY','Watch. Understand. Practice.','Free chess lessons collected by topic. Videos open on Lichess; your training site stays free.')+
 '<p class="lesson-copy">These links open curated free-video searches on Lichess. We are not copying or rehosting creators’ videos. Watch a lesson, then return to Knight School to practice its ideas.</p>'+
 '<div class="catalog">'+topics.map(t=>'<article class="catalog-card"><span class="pill">'+esc(t[0])+'</span><h3>'+esc(t[1])+'</h3><p>'+esc(t[3])+'</p><a class="secondary" href="'+t[2]+'" target="_blank" rel="noopener noreferrer">Watch free videos ↗</a></article>').join('')+'</div>'+
 '<div class="button-row"><a class="primary" href="#guided">Practice guided openings →</a><a class="secondary" href="#strategy">Practice tactics →</a></div>';
}

function catalogOrPage(){if(page==='guided')guidedCatalog();else if(page==='analysis')analysisLanding();else if(page==='mistakes')mistakeLanding();else if(page==='videos')videoAcademy();else if(['openings','strategy','endgames'].includes(page))catalog();else if(page==='masters')masterCatalog();else if(page==='review')review();else if(page==='practice')practice();else today()}
function route(){const dest=location.hash.slice(1).split('?')[0]||'today';page=names[dest]?dest:'today';search='';catalogPage=0;renderNav();catalogOrPage();window.scrollTo(0,0)}
document.addEventListener('click',e=>{const sq=e.target.closest('[data-square]');if(sq){squareClick(sq.dataset.square);return}const act=e.target.closest('[data-action]');if(act){onAction(act.dataset.action);return}const open=e.target.closest('[data-open]');if(open){openStudy(open.dataset.open);window.scrollTo(0,0);return}const st=e.target.closest('[data-step]');if(st&&!drill&&!playing){pausePlayback();step=Number(st.dataset.step);feedback='';setPosition();renderBoard();renderPanel();return}if(e.target.id==='previousPage'){catalogPage--;renderCatalogCards();window.scrollTo(0,180)}if(e.target.id==='nextPage'){catalogPage++;renderCatalogCards();window.scrollTo(0,180)}if(e.target.id==='savedFilter'){savedOnly=!savedOnly;catalogPage=0;$('#savedFilter').textContent=savedOnly?'✓ Saved openings':'♡ Saved openings';renderCatalogCards()}if(e.target.id==='importPgn')importText($('#pgnInput').value);if(e.target.id==='sampleGame'){$('#pgnInput').value=masters[0].pgn;importText(masters[0].pgn)}});
document.addEventListener('input',e=>{if(e.target.id==='search'){search=e.target.value;catalogPage=0;renderCatalogCards()}});document.addEventListener('change',async e=>{if(e.target.id==='ecoFilter'){eco=e.target.value;catalogPage=0;renderCatalogCards()}if(e.target.id==='pgnFile'&&e.target.files[0]){if(e.target.files[0].size>500000){toast('Please choose a single game file smaller than 500 KB.');return}const text=await e.target.files[0].text();$('#pgnInput').value=text;importText(text)}});
document.addEventListener('keydown',e=>{if(['INPUT','TEXTAREA','SELECT'].includes(e.target.tagName)||$('#modal').open)return;if(e.key==='ArrowRight'){e.preventDefault();if(!drill&&!playing)onAction('next')}if(e.key==='ArrowLeft'){e.preventDefault();if(!drill&&!playing)onAction('prev')}});
$('#closeModal').onclick=()=>$('#modal').close();$('#aboutButton').onclick=about;$('#progressButton').onclick=progressModal;$('.mobile-brand').onclick=()=>$('.sidebar').classList.toggle('open');window.addEventListener('hashchange',route);
try{const theme=localStorage.getItem('knight-school-board-theme');document.documentElement.dataset.boardTheme=['walnut','tournament','slate'].includes(theme)?theme:'walnut'}catch{document.documentElement.dataset.boardTheme='walnut'}
try{openings=await fetch('./openings.json').then(r=>{if(!r.ok)throw new Error();return r.json()});openings=openings.map((x,i)=>({...x,id:'eco-'+i,tokens:x.pgn.replace(/\d+\.(?:\.\.)?/g,' ').trim().split(/\s+/)}))}catch{toast('The full opening library could not load. Guided lessons are still available.')}try{const more=await fetch('./master-games.json').then(r=>r.json());masters.push(...more);for(let i=0;i<masters.length;i++)masters[i]=enrichMaster(masters[i])}catch{toast('Extra master games could not load. The original games are available.')}route();

function practiceSideSelect(){return `<div class="study-options"><label for="drillSide">Practice as</label><select id="drillSide"><option value="w" ${drillSide==='w'?'selected':''}>White</option><option value="b" ${drillSide==='b'?'selected':''}>Black</option><option value="both" ${drillSide==='both'?'selected':''}>Both sides</option></select></div>`}
function pausePlayback(){autoplayRunning=false;clearTimeout(playbackTimer);playbackTimer=null;updatePlaybackControls()}
function updatePlaybackControls(){const b=$('#autoplayButton');if(!b)return;b.textContent=autoplayRunning?'Ⅱ Pause playback':'▶ Play through';b.disabled=drill||playing||!line.length;if($('#playbackSpeed'))$('#playbackSpeed').value=String(autoplaySeconds);if($('#playbackStatus'))$('#playbackStatus').textContent=autoplayRunning?`Next move in ${autoplaySeconds} seconds.`:step===line.length&&line.length?'Line finished. Replay or study the result.':'Pause any time to study or ask.'}
function beginPlayback(){if(drill||playing||!line.length)return;pausePlayback();if(step>=line.length){step=0;setPosition()}autoplayRunning=true;const tick=()=>{if(!autoplayRunning)return;if(step>=line.length){pausePlayback();return}step++;setPosition();renderBoard();renderPanel();if(step>=line.length){pausePlayback();return}playbackTimer=setTimeout(tick,autoplaySeconds*1000)};updatePlaybackControls();tick()}
function setEngineResult(result){const top=result.lines[0];engineResult={fen:result.fen,depth:top?.depth||0,mate:top?.mateWhite??null,whiteScore:top?.scoreWhite??(top?.mateWhite!=null?(top.mateWhite>=0?20:-20):0),lines:result.lines,sanLine:top?.san.join(' ')||'',explain:engineExplanation(result.fen,result.bestMove)}}
async function reviewLastMove(){
 pausePlayback();const m=chess.history({verbose:true}).at(-1);if(!m){toast('Make or select a move first.');return}
 stopEngine();const token=engineToken,fen=chess.fen();engineBusy=true;renderPanel();
 try{
  let task=searchPosition(m.before,{time:analysisTime,multipv:3});engine=task;const before=await task.promise;if(token!==engineToken)return;
  if(chess.isGameOver()){
   const mate=chess.isCheckmate(),terminal={scoreWhite:mate?null:0,mateWhite:mate?(chess.turn()==='b'?1:-1):null,terminal:mate?'checkmate':'draw',san:[],uci:[],depth:before.lines[0]?.depth||0};
   engineBusy=false;engine=null;engineResult={fen,depth:terminal.depth,mate:terminal.mateWhite,whiteScore:mate?(terminal.mateWhite>0?20:-20):0,lines:[],explain:mate?'The move delivered checkmate.':'The move ended the game in a draw.',moveReview:{before:before.lines,played:m.san,after:[terminal],mover:side(m.color),summary:mate?`${side(m.color)} played ${m.san}: checkmate.`:`${m.san} ended the game in a draw. Compare the earlier winning chances, if any.`}};saveAnalyzedMistake();renderBoard();renderPanel();return;
  }
  task=searchPosition(fen,{time:analysisTime,multipv:3});engine=task;const after=await task.promise;if(token!==engineToken||fen!==chess.fen())return;
  engineBusy=false;engine=null;setEngineResult(after);const a=before.lines[0],b=after.lines[0],loss=Number.isFinite(a?.scoreWhite)&&Number.isFinite(b?.scoreWhite)?(a.scoreWhite-b.scoreWhite)*(m.color==='w'?1:-1):null;
  const fmt=x=>!x?'unavailable':x.mateWhite!==null?'mate '+x.mateWhite:(x.scoreWhite>=0?'+':'')+x.scoreWhite.toFixed(2);
  engineResult.moveReview={before:before.lines,played:m.san,after:after.lines,loss,mover:side(m.color),summary:`${side(m.color)} played ${m.san}. Before: ${fmt(a)}; after: ${fmt(b)} (White’s perspective). ${loss===null?'A mate estimate is involved; do not compare it as a pawn score.':loss>.2?`The short search estimates a loss of about ${loss.toFixed(2)} pawn units for the mover.`:loss<-.2?'The two searches changed their assessment; analyze longer before drawing a conclusion.':'The move stayed close to the engine’s previous estimate.'} The earlier candidate was ${a?.san[0]||'not available'}.`};saveAnalyzedMistake();renderBoard();renderPanel();
 }catch(error){if(error.name==='AbortError'||token!==engineToken)return;engineBusy=false;engineError=error.message;renderPanel()}
}
function openingBranchData(){if(lessonType!=='opening'||free||drill)return [];const history=chess.history();const groups=new Map();for(const o of openings){if(o.tokens.length<=history.length||!history.every((m,i)=>o.tokens[i]===m))continue;const next=o.tokens[history.length];if(!groups.has(next))groups.set(next,{move:next,id:o.id,name:o.name,count:0});groups.get(next).count++}return [...groups.values()].sort((a,b)=>b.count-a.count).slice(0,10)}
function threadKey(){return lesson?.id||page}
function thread(){const key=threadKey();if(!coachThreads.has(key))coachThreads.set(key,[]);return coachThreads.get(key)}
function learningContext(){const explanation=explainMove(chess,lesson),m=explanation.move;return {fen:chess.fen(),turn:side(chess.turn()),history:chess.pgn(),selectedLine:{startFen:startFen||new Chess().fen(),moves:line,currentPly:step},lesson:lesson?.name||reviewName||'Free practice',lastMove:m?{san:m.san,color:m.color,before:m.before}:null,studyNotes:[lesson?.description,lesson?.text,lesson?.plan,lesson?.study?.why,generalNote(),explanation.authored,planText(chess,'w',lesson),planText(chess,'b',lesson)].filter(Boolean).join('\n\n'),positionFacts:JSON.stringify(explanation.position),engine:engineResult?.fen===chess.fen()?{lines:engineResult.lines,review:engineResult.moveReview}:null}}
function renderLearningExtras(){
 const workspace=$('.workspace');if(!workspace)return;if(!workspace.closest('.study-layout')){const layout=document.createElement('div');layout.className='study-layout';workspace.before(layout);layout.append(workspace)}let box=$('#learningExtras');if(!box){workspace.insertAdjacentHTML('afterend','<div id="learningExtras" class="learning-grid"></div>');box=$('#learningExtras')}
 const focusedId=document.activeElement?.id,focused=focusedId==='coachQuestion'||focusedId==='coachAnswer',selectionStart=focused?document.activeElement.selectionStart:null;
 const e=explainMove(chess,lesson),m=e.move,f=e.position,theory=e.theory,study=lesson?.study,branches=openingBranchData();
 const note=m?(lesson?.players&&lesson.notes?.[step])||e.authored||e.facts[0]:study?.why||theory?.structure||'Choose a move to inspect its purpose, then compare both players’ plans.';
 box.innerHTML=`<article class="deep-study"><div class="section-heading"><div><p class="eyebrow">THE REASON BEHIND THE MOVE</p><h2>${m?`${side(m.color)} played ${esc(m.san)}`:'Understand the position.'}</h2></div><button class="secondary" data-action="reviewMove" ${!m||playing?'disabled':''}>Review this move</button></div><div class="focus-tabs" role="group" aria-label="Study perspective">${[['both','Both sides'],['w','White’s ideas'],['b','Black’s ideas']].map(([value,label])=>`<button data-study-focus="${value}" class="${studyFocus===value?'active':''}">${label}</button>`).join('')}</div><p class="lead-explanation">${esc(note)}</p>${m?`<h3>What changed on the board?</h3><ul class="reason-list">${e.facts.map(x=>`<li>${esc(x)}</li>`).join('')}</ul>`:''}${study?.why?`<details class="study-details" open><summary>The deeper theory</summary><p>${esc(study.why)}</p></details>`:''}${theory?`<details class="study-details" open><summary>Pawn structure and tradeoffs</summary><p>${esc(theory.structure)}</p></details>`:''}<div class="side-plans">${['w','b'].filter(c=>studyFocus==='both'||studyFocus===c).map(c=>`<section><h3><span class="plan-piece">${c==='w'?'♔':'♚'}</span> ${side(c)}’s plan</h3><p>${esc(planText(chess,c,lesson))}</p></section>`).join('')}</div>${studyFocus!=='both'?`<details class="study-details"><summary>The opponent’s resources</summary><p>${esc(planText(chess,studyFocus==='w'?'b':'w',lesson))}</p></details>`:''}<details class="study-details"><summary>How to assess this position</summary><p><b>Material:</b> White ${f.material.w}, Black ${f.material.b} using rough piece values. Activity and king safety can outweigh this count.</p><p><b>Central pressure:</b> White attacks ${f.center.w.join(', ')||'none of the four central squares'}; Black attacks ${f.center.b.join(', ')||'none of the four central squares'}.</p><p><b>Pieces to inspect:</b> White ${f.loose.w.join(', ')||'has no geometrically undefended attacked piece detected'}; Black ${f.loose.b.join(', ')||'has no geometrically undefended attacked piece detected'}. This scan is not a tactical proof.</p><ol>${(study?.steps||['Check the opponent’s threats.','Compare checks, captures, and forcing threats.','Identify the weakest piece and the useful pawn break.','Calculate the strongest reply before choosing.']).map(x=>`<li>${esc(x)}</li>`).join('')}</ol></details><div class="reflection"><span class="mini-label">CHECK YOUR UNDERSTANDING</span><h3>${esc(study?.question||theory?.question||'What would your opponent most like to do next?')}</h3><details><summary>Reveal the reasoning</summary><p>${esc(study?.answer||theory?.answer||'Look for checks, captures, pawn breaks, and useful piece improvements. Your plan should account for the opponent’s strongest idea, not only your own threat.')}</p></details></div>${branches.length?`<div class="theory-branches"><h3>Other theory moves from here</h3><p>These are named continuations in the library, not a ranking of playing strength.</p><div class="branch-buttons">${branches.map(b=>`<button class="secondary" data-opening-branch="${b.id}" title="${esc(b.name)}">${esc(b.move)} <small>${b.count} ${b.count===1?'line':'lines'}</small></button>`).join('')}</div></div>`:''}<div class="alternative-box"><label for="alternativeMove" class="mini-label">WHAT IF I PLAY SOMETHING ELSE?</label><div class="alternative-row"><input id="alternativeMove" class="search" placeholder="A legal move, such as Nf3 or e2e4" aria-label="Alternative move"><button class="secondary" data-action="tryAlternative" ${playing?'disabled':''}>Try move</button></div>${compareNote?`<p>${esc(compareNote)}</p>`:''}${free&&page!=='practice'?'<button class="secondary" data-action="returnLine">Return to studied line</button>':''}</div></article>${renderFreeCoachPanel()}`;
 if(focused&&document.getElementById(focusedId)){const input=document.getElementById(focusedId);input.focus({preventScroll:true});input.setSelectionRange(selectionStart,selectionStart)}
}
async function askCoach(_unused=false,override){
 pausePlayback();const question=(override??$('#coachQuestion')?.value??coachDraft).trim();if(!question){toast('Enter a chess question first.');return}if(coachBusy)return;
 const fen=chess.fen(),key=threadKey(),move=chess.history().at(-1)||'Starting position',frozenLesson=lesson;
 latestCoachQuestions.set(key,question);coachDraft='';coachError='';coachBusy=true;renderLearningExtras();
 try{
  if(/blunder|mistake|miss|better|tactic|wrong|lose|lost/.test(question.toLowerCase())&&(!engineResult||engineResult.fen!==fen||(!engineResult.moveReview&&chess.history().length))){
   if(chess.history().length)await reviewLastMove();else if(!chess.isGameOver())await analyze();
  }
  if(chess.fen()!==fen||threadKey()!==key){toast('The board changed. Ask again about the new position.');return}
  const log=thread();log.push({role:'user',text:question,move},{role:'assistant',text:freeCoachReply(question,chess,frozenLesson,engineResult),source:'guide',move});saveChats();
 }catch{coachError='The local engine could not finish. Try Analyze candidates again.'}
 finally{coachBusy=false;if($('#learningExtras'))renderLearningExtras()}
}
function onAction(action){
 if(['first','prev','next','last','reset','back','playPosition','play','undo'].includes(action))pausePlayback();
 if(action==='autoplay'){autoplayRunning?pausePlayback():beginPlayback();return}
 if(action==='hint'){showHint();return}
 if(action==='askGuide'){askCoach();return}if(action==='askChatGPT'){openChatGPTHandoff();return}
 if(action==='deepCoach'){askCoach(false,'Explain why this move works, the theory, and both players’ plans.');return}
 if(action==='copyContext'){copyCoachingPrompt();return}
 if(['coachSubmit','coachNext','coachBack','coachRestart'].includes(action)){navigateCoachQuestion(action);return}
 if(action==='reviewMove'){reviewLastMove();return}
 if(action==='returnLine'){free=false;compareNote='';setPosition();renderBoard();renderPanel();return}
 if(action==='tryAlternative'){const text=$('#alternativeMove').value.trim().replace(/^\d+\.{1,3}\s*/,'');try{const c=new Chess(chess.fen());let m;if(/^[a-h][1-8][a-h][1-8][qrbn]?$/.test(text))m=c.move({from:text.slice(0,2),to:text.slice(2,4),promotion:text[4]||'q'});else m=c.move(text);drill=false;compareNote=`Exploring ${m.san}. Use Review this move to compare the engine’s before-and-after estimates.`;attemptMove({from:m.from,to:m.to,promotion:m.promotion||'q'})}catch{toast('That move is not legal in the displayed position. Try standard notation such as Nf3 or e2e4.')}return}
 if(action==='exercise'){pausePlayback();drillSide=$('#drillSide')?.value||new Chess(startFen||undefined).turn();step=0;setPosition();drill=true;autoReply();if(step===line.length){drill=false;feedback='This short example has no move for that side. Select the side that starts the line.'}else feedback=`Practice the technique as ${drillSide==='both'?'both sides':side(drillSide)}.`;feedbackError=false;renderBoard();renderPanel();return}
 if(action==='solution'){pausePlayback();step=line.length;setPosition();drill=false;feedback='Line revealed. Replay it move by move, then test your recall.';feedbackError=false;renderBoard();renderPanel();return}
 legacyAction(action);
}
document.addEventListener('click',e=>{
 const focus=e.target.closest('[data-study-focus]');if(focus){studyFocus=focus.dataset.studyFocus;if(studyFocus!=='both'){flipped=studyFocus==='b';renderBoard()}renderLearningExtras();return}
 const prompt=e.target.closest('[data-coach-prompt]');if(prompt){coachDraft=prompt.dataset.coachPrompt;$('#coachQuestion').value=coachDraft;$('#coachQuestion').focus();pausePlayback();return}
 const branch=e.target.closest('[data-opening-branch]');if(branch){const nextStep=step+1;pausePlayback();openStudy(branch.dataset.openingBranch,nextStep);return}
});
document.addEventListener('input',e=>{if(e.target.id==='coachQuestion')coachDraft=e.target.value;if(e.target.id==='masterSearch'){const q=e.target.value.toLowerCase();document.querySelectorAll('[data-master-search]').forEach(el=>el.hidden=!el.dataset.masterSearch.includes(q))}});
document.addEventListener('change',e=>{if(e.target.id==='playbackSpeed'){autoplaySeconds=Number(e.target.value);if(autoplayRunning)beginPlayback();else updatePlaybackControls()}if(e.target.id==='analysisTime')analysisTime=Number(e.target.value)});
document.addEventListener('visibilitychange',()=>{if(document.hidden)pausePlayback()});

function boardFromContext(context){const board=new Chess(context.fen);try{if(context.history)board.loadPgn(context.history)}catch{}return board}

function saveChats(){try{localStorage.setItem('knight-school-chats-v2',JSON.stringify([...coachThreads.entries()].slice(-20).map(([key,messages])=>[key,messages.slice(-40)])))}catch{}}

function activeQuestionData(){
 const key=threadKey()+'::'+chess.fen().split(' ').slice(0,4).join(' ');
 if(!questionSessions.has(key))questionSessions.set(key,makeQuestionState());
 const state=questionSessions.get(key),deck=questionDeck(chess,lesson,engineResult?.fen===chess.fen()?engineResult:null);
 return {key,state,deck,...currentQuestion(state,deck)};
}
function saveQuestionSessions(){try{localStorage.setItem('knight-school-questions-v1',JSON.stringify([...questionSessions.entries()].map(([key,state])=>[key,{...state,history:state.history}])))}catch{}}
function renderFreeCoachPanel(){
 const q=activeQuestionData(),report=coachReport(chess,engineResult),log=thread(),latest=[...log].reverse().find(x=>x.role==='assistant');
 return `<aside class="ask-coach" aria-label="Free Coach"><div class="section-heading"><div><p class="eyebrow">FREE COACH</p><h2>Understand. Answer. Keep learning.</h2></div><span class="coach-dot"></span></div><p class="coach-connection">Stockfish + programmed explanations · no API credits</p><section id="coachQuestionContainer" class="coach-question-container" tabindex="-1" aria-label="Current Coach question"><div class="question-heading"><span class="mini-label">QUESTION ${q.number} OF ${q.deck.length} · ROUND ${q.round}</span><span class="mini-label">${side(chess.turn())} to move</span></div><h3 id="activeCoachQuestion">${esc(q.item.question)}</h3><label for="coachAnswer" class="mini-label">YOUR ANSWER</label><textarea id="coachAnswer" placeholder="Explain your thinking in your own words…" maxlength="2500">${esc(q.state.draft)}</textarea><button class="primary" data-action="coachSubmit">Submit answer & next →</button><div class="question-navigation" role="group" aria-label="Coach question navigation"><button class="secondary" data-action="coachBack" ${q.state.cursor===0?'disabled':''}>← Back</button><button class="secondary" data-action="coachNext">Next →</button><button class="secondary" data-action="coachRestart">Restart</button></div><p class="notice">Your answer is saved, then the next question appears. Compare your reasoning with the explanation in history; free-text answers are not automatically graded.</p></section><details class="coach-history"><summary>Previous Coach questions & explanations (${q.state.history.length})</summary><div class="question-history-list">${[...q.state.history].reverse().map(x=>`<article><h4>${esc(x.question)}</h4><p><b>Your answer:</b> ${esc(x.answer)}</p><div class="chat-text"><b>Explanation:</b> ${esc(x.explanation)}</div></article>`).join('')||'<p>No answers saved for this position yet.</p>'}</div></details><section class="free-engine-coaching" aria-label="Free engine explanations"><h3>What Stockfish and the board show</h3><p>${esc(report.summary)}</p>${report.classification?`<div class="move-grade grade-${esc(report.classification.code||'unrated')}"><span>MOVE QUALITY · SHORT SEARCH</span><strong>${esc(report.classification.label)}</strong>${report.classification.loss!==null?`<small>Estimated change: ${Math.max(0,report.classification.loss).toFixed(2)} pawn units for the mover</small>`:''}</div>`:''}${report.alerts.map(a=>`<article class="coach-finding"><h4>${esc(a.title)}</h4><p>${esc(a.text)}</p></article>`).join('')}<div class="button-row"><button class="secondary" data-action="reviewMove" ${!chess.history().length||playing?'disabled':''}>Review my last move</button><button class="secondary" data-action="analyze" ${playing?'disabled':''}>Analyze candidates</button></div></section><section class="coach-ask-form"><h3>Ask the free Coach</h3><div class="question-chips">${['Why this move?','What is White’s plan?','What is Black’s plan?','What did I miss?'].map(text=>`<button data-coach-prompt="${esc(text)}">${text}</button>`).join('')}</div><label for="coachQuestion" class="mini-label">YOUR CHESS QUESTION</label><textarea id="coachQuestion" placeholder="Ask about the plan, threats, or your last move…" maxlength="2500">${esc(coachDraft)}</textarea><div class="button-row"><button class="primary" data-action="askGuide" ${coachBusy?'disabled':''}>${coachBusy?'Analyzing locally…':'Ask free Coach'}</button><button class="secondary" data-action="deepCoach" ${coachBusy?'disabled':''}>Explain the idea</button></div>${coachError?`<div class="feedback error" role="status">${esc(coachError)}</div>`:''}${latest?`<article class="current-coach-reply" aria-label="Latest Coach explanation"><span class="mini-label">LATEST EXPLANATION · ${esc(latest.move||'')}</span><div class="chat-text">${esc(latest.text)}</div></article>`:''}<details class="coach-history"><summary>Previous conversations (${log.filter(x=>x.role==='user').length})</summary><div class="chat-log" role="log" aria-label="Coach conversation">${log.map(x=>`<div class="chat-message ${x.role}"><span class="chat-role">${x.role==='user'?'YOU':x.source==='ai'?'EARLIER AI ANSWER':'FREE COACH'} · ${esc(x.move||'')}</span><div class="chat-text">${esc(x.text)}</div></div>`).join('')||'<p>No conversation history yet.</p>'}</div></details></section><section class="chatgpt-handoff"><h3>Want a longer conversation?</h3><p>Ask ChatGPT shows your question and complete chess position first. Copy the prompt, then choose when to open ChatGPT. You can save a direct link to your chess project or an existing conversation.</p><div class="button-row"><button class="primary" data-action="askChatGPT">Ask ChatGPT ↗</button><button class="secondary" data-action="copyContext">Copy coaching prompt</button></div><p class="notice">For a fuller prompt, use Review my last move first. No moves are sent automatically, and ChatGPT is not embedded here.</p></section><div class="analysis-options"><label for="analysisTime">Analysis time</label><select id="analysisTime"><option value="1800" ${analysisTime===1800?'selected':''}>Quick · 2 sec</option><option value="5000" ${analysisTime===5000?'selected':''}>Deeper · 5 sec</option><option value="10000" ${analysisTime===10000?'selected':''}>Study · 10 sec</option></select><button class="secondary" data-action="glossary">Chess terms explained</button></div></aside>`;
}
function navigateCoachQuestion(action){
 pausePlayback();const q=activeQuestionData(),draft=$('#coachAnswer')?.value??q.state.draft;
 if(action==='coachSubmit'){if(!submitQuestion(q.state,q.deck,draft)){toast('Write an answer, or use Next to skip.');$('#coachAnswer')?.focus();return}}
 if(action==='coachNext'){if(draft.trim())submitQuestion(q.state,q.deck,draft);else nextQuestion(q.state)}
 if(action==='coachBack')previousQuestion(q.state);
 if(action==='coachRestart')restartQuestions(q.state);
 saveQuestionSessions();renderLearningExtras();focusCurrentCoachQuestion();
}
function focusCurrentCoachQuestion(){
 const target=$('#coachQuestionContainer');if(!target)return;
 target.scrollTop=0;const panel=target.closest('.ask-coach');if(panel)panel.scrollTop=0;
 try{target.focus({preventScroll:true})}catch{target.focus()}
 target.scrollIntoView({block:'start',behavior:'auto'});
}
function coachingPrompt(question){return buildChatGPTPrompt(learningContext(),question??$('#coachQuestion')?.value??coachDraft)}
function savedChessChatUrl(){try{return localStorage.getItem('knight-school-chatgpt-destination')||''}catch{return ''}}
function validChessChatUrl(value){
 try{const url=new URL(value);return url.protocol==='https:' && ['chatgpt.com','chat.openai.com'].includes(url.hostname)&&!url.port&&!url.username&&!url.password&&![...url.searchParams.keys()].some(k=>/^(q|prompt|message|text)$/i.test(k)) ? url.href : ''}catch{return ''}
}
function showChatGPTHandoff(){
 pausePlayback();
 const question=($('#coachQuestion')?.value||coachDraft||latestCoachQuestions.get(threadKey())||[...thread()].reverse().find(x=>x.role==='user')?.text||'Explain this position, my last move, the opponent’s threats, and a useful plan.').trim();
 const initialPrompt=coachingPrompt(question);
 modal(`<h2>Ask ChatGPT about this position</h2><p>Review your question, copy the complete prompt, and <b>then</b> choose when to open ChatGPT. Nothing opens automatically.</p><label for="chatgptQuestion" class="mini-label">YOUR QUESTION — INCLUDED IN THE PROMPT</label><textarea id="chatgptQuestion" class="prompt-fallback" style="min-height:90px" maxlength="2500">${esc(question)}</textarea><label for="chatgptPrompt" class="mini-label">COMPLETE COACHING PROMPT</label><textarea id="chatgptPrompt" class="prompt-fallback" readonly>${esc(initialPrompt)}</textarea><p id="copyPromptStatus" role="status">Step 1: Copy your prompt. Step 2: Open your chosen ChatGPT conversation.</p><div class="button-row"><button class="primary" id="copyPromptNow">Copy complete prompt</button><button class="secondary" id="selectPrompt">Select all</button><button class="secondary" id="manualCopyDone" hidden>I copied it manually</button></div><label for="chessChatDestination" class="mini-label">YOUR CHESS PROJECT OR CONVERSATION LINK (OPTIONAL)</label><input id="chessChatDestination" type="url" inputmode="url" placeholder="Paste your ChatGPT project link here" value="${esc(savedChessChatUrl())}" style="width:100%;max-width:100%;font-size:16px;padding:11px"><button class="secondary" id="saveChessChatDestination">Save destination</button><p class="notice">To open your existing chess project: open it in ChatGPT, copy its browser URL, and paste it here once. Knight School saves the link on this device. ChatGPT may still ask you to select a conversation inside that project.</p><div class="button-row"><button class="secondary" id="openChatGPTNow">Open ChatGPT (after copying) ↗</button></div><p class="notice">The prompt is not automatically pasted or sent. Paste it into ChatGPT and press Send. No API credits are used.</p>`);
 const promptField=$('#chatgptPrompt'),questionField=$('#chatgptQuestion'),status=$('#copyPromptStatus'),dest=$('#chessChatDestination'),open=$('#openChatGPTNow');
 let copied=false;
 open.disabled=true;
 questionField.addEventListener('input',()=>{coachDraft=questionField.value;promptField.value=coachingPrompt(questionField.value);copied=false;open.disabled=true;$('#manualCopyDone').hidden=true;status.textContent='Question updated. Copy the new prompt before opening ChatGPT.'});
 dest.addEventListener('change',()=>{const value=dest.value.trim();if(!value){try{localStorage.removeItem('knight-school-chatgpt-destination')}catch{}return}const checked=validChessChatUrl(value);if(!checked){status.textContent='That destination is not a secure ChatGPT link. Paste a URL beginning with https://chatgpt.com/';return}dest.value=checked;try{localStorage.setItem('knight-school-chatgpt-destination',checked)}catch{}status.textContent='Chess ChatGPT destination saved on this device.'});
 $('#saveChessChatDestination').onclick=()=>dest.dispatchEvent(new Event('change',{bubbles:true}));
 $('#selectPrompt').onclick=()=>{promptField.focus();promptField.select();promptField.setSelectionRange(0,promptField.value.length);status.textContent='Prompt selected. Use Copy, then open ChatGPT.'};
 $('#copyPromptNow').onclick=async()=>{
   const value=promptField.value;
   try{if(!navigator.clipboard?.writeText)throw Error('Clipboard unavailable');await navigator.clipboard.writeText(value);if(promptField.value!==value){copied=false;open.disabled=true;status.textContent='Question changed. Copy the updated prompt.';return}copied=true;open.disabled=false;status.textContent='Complete prompt copied, including your question! Now you can open ChatGPT.'}
   catch{copied=false;open.disabled=true;promptField.focus();promptField.select();status.textContent='Safari blocked automatic copying. The prompt is selected: use Copy from the text selection. Confirm with “I copied it manually” after copying.';$('#manualCopyDone').hidden=false}
 };
 $('#manualCopyDone').onclick=()=>{copied=true;open.disabled=false;status.textContent='Manual copy confirmed. Open ChatGPT, paste the prompt, then send it.'};
 open.onclick=()=>{if(!copied)return;const value=dest.value.trim(),target=value?validChessChatUrl(value):'https://chatgpt.com/';if(!target){status.textContent='Invalid ChatGPT project link. Remove it or paste a proper ChatGPT URL.';return}if(value){try{localStorage.setItem('knight-school-chatgpt-destination',target)}catch{}}window.open(target,'_blank','noopener,noreferrer');status.textContent='ChatGPT opened. Paste your copied prompt there and send it.'};
}
function openChatGPTHandoff(){showChatGPTHandoff()}
function copyCoachingPrompt(){showChatGPTHandoff()}
document.addEventListener('input',e=>{if(e.target.id==='coachAnswer'){const q=activeQuestionData();q.state.draft=e.target.value;saveQuestionSessions()}});

try{const theme=localStorage.getItem('knight-school-board-theme');document.documentElement.dataset.boardTheme=['walnut','tournament','slate'].includes(theme)?theme:'walnut'}catch{document.documentElement.dataset.boardTheme='walnut'}
document.addEventListener('change',e=>{if(e.target.id==='boardTheme'){document.documentElement.dataset.boardTheme=e.target.value;try{localStorage.setItem('knight-school-board-theme',e.target.value)}catch{}}});

function persistTraining(){try{localStorage.setItem(trainingKey,JSON.stringify(training));return true}catch{toast('Training data could not be saved. Download a backup before closing this tab.');return false}}
function sideName(s){return s==='both'?'Both sides':side(s)}
function studyName(id){return [...families,...openings,...strategies,...endgames,...masters].find(x=>x.id===id)?.name||id}
function dateLabel(value){return new Date(value).toLocaleString(undefined,{month:'short',day:'numeric',hour:'numeric',minute:'2-digit'})}
function reviewQueueSummary(){const due=dueReviews(training).length;return `<div class="review-queue-banner"><div><span class="mini-label">YOUR NEXT REVIEW</span><h3>${due?due+' opening '+(due===1?'review is':'reviews are')+' ready':'Build a repertoire that stays with you.'}</h3><p>Spaced practice, a mistake notebook, and complete progress backups.</p></div><button class="secondary" data-training-progress>Training progress →</button></div>`}
function finishRecall(){
 const key=reviewKey(lesson.id,drillSide),previous=training.reviews[key],now=Date.now();pendingRecallResult={lessonId:lesson.id,side:drillSide,previous,now};
 const grade=drillErrors?'again':drillHints?'hard':'good';training.reviews[key]=scheduleReview(previous,{lessonId:lesson.id,side:drillSide,grade,now});
 training.sessions.push({id:globalThis.crypto?.randomUUID?.()||String(now)+'-'+Math.random().toString(36).slice(2),at:new Date(now).toISOString(),lessonId:lesson.id,side:drillSide,errors:drillErrors,hints:drillHints});persistTraining();
}
function recallResultMarkup(){if(!pendingRecallResult||pendingRecallResult.lessonId!==lesson?.id||drill)return '';const r=training.reviews[reviewKey(pendingRecallResult.lessonId,pendingRecallResult.side)];return `<section class="recall-result" aria-label="Opening recall result"><span class="mini-label">SPACED PRACTICE · ${sideName(r.side)}</span><h3>Next review: ${dateLabel(r.due)}</h3><p>${drillErrors} missed moves · ${drillHints} hints. Adjust how well you remembered this line:</p><div class="recall-ratings">${[['again','Again · 10 min'],['hard','Hard'],['good','Good'],['easy','Easy']].map(([g,t])=>`<button class="secondary ${r.grade===g?'active':''}" data-recall-grade="${g}" aria-pressed="${r.grade===g}">${t}</button>`).join('')}</div></section>`}
function saveAnalyzedMistake(){const m=createMistake(chess,engineResult,lesson?.id||page);if(rememberMistake(training,m))persistTraining()}
function mistakeStudyMarkup(){const m=activeMistakeId&&training.mistakes.find(x=>x.id===activeMistakeId);if(!m||page!=='practice')return '';return `<section class="mistake-study" aria-label="Mistake recall"><span class="mini-label">YOUR MISTAKE NOTEBOOK</span><h3>Find a better move than ${esc(m.played)}.</h3><p>${side(m.mover)} to move in the original position. Try the earlier engine candidate on the board.</p><details><summary>Reveal candidate and explanation</summary><p><b>${esc(m.bestMove)}</b> · ${esc(m.line.slice(0,8).join(' '))}</p><div class="chat-text">${esc(m.explanation)}</div></details><button class="secondary" data-training-progress>Back to training record</button></section>`}
function checkNotebookMove(move){const m=activeMistakeId&&training.mistakes.find(x=>x.id===activeMistakeId);if(!m||move.before!==m.fenBefore)return;if(move.from+move.to+(move.promotion||'')===m.bestUci){m.reviewCount=(m.reviewCount||0)+1;m.reviewedAt=new Date().toISOString();persistTraining();feedback='You found the earlier Stockfish candidate. Study the reply and compare the explanation.'}else feedback='That is legal. Compare it with the earlier candidate in your mistake notebook.'}
function exportFullBackup(){try{saveChats();saveQuestionSessions();const backup=makeBackup(localStorage);download('knight-school-backup-'+day()+'.json',JSON.stringify(backup,null,2),'application/json')}catch(e){toast('Backup could not be created: '+e.message)}}
function showRestore(){
 let restoreGeneration=0;restoreCandidate=null;modal(`<p class="eyebrow">BACKUP & RESTORE</p><h2>Bring your training back.</h2><p>Choose a Knight School JSON backup, or paste one below. The file is checked before anything changes. Restore merges records and keeps your current device settings.</p><label class="secondary" for="backupFile">Choose backup file</label><input id="backupFile" type="file" accept=".json,application/json" hidden><label class="mini-label" for="backupText">Or paste backup JSON</label><textarea id="backupText" class="prompt-fallback" placeholder="Paste your backup JSON here…"></textarea><button class="secondary" id="previewBackup">Check backup</button><p id="restoreStatus" role="status"></p><div id="restoreSummary"></div><button class="primary" id="applyBackup" disabled>Back up current data & merge</button><p class="notice">A safety backup of current data downloads before the merge. Legacy progress-only exports are also accepted. Counts use the larger value to avoid double-counting repeated imports.</p>`);
 function check(text,generation=restoreGeneration){if(generation!==restoreGeneration||!$('#restoreStatus'))return;try{restoreCandidate=parseBackup(text);const p=restoreCandidate.records['knight-school-v1'],t=restoreCandidate.records[trainingKey];$('#restoreSummary').innerHTML=`<div class="coach-note"><b>Ready to merge</b><p>${Object.keys(restoreCandidate.records).length} records · ${p?.done.length||0} completed lessons · ${t?.mistakes.length||0} saved mistakes · ${Object.keys(t?.reviews||{}).length} opening schedules</p></div>`;$('#restoreStatus').textContent='Backup validated. Existing records will be retained.';$('#applyBackup').disabled=false}catch(e){restoreCandidate=null;$('#applyBackup').disabled=true;$('#restoreSummary').innerHTML='';$('#restoreStatus').textContent=e.message}}
 $('#previewBackup').onclick=()=>{restoreGeneration++;check($('#backupText').value)};$('#backupText').oninput=()=>{restoreGeneration++;restoreCandidate=null;$('#applyBackup').disabled=true};
 $('#backupFile').onchange=async e=>{const file=e.target.files[0];if(!file)return;const generation=++restoreGeneration;restoreCandidate=null;$('#applyBackup').disabled=true;$('#restoreStatus').textContent='Reading backup…';if(file.size>8*1024*1024){$('#restoreStatus').textContent='Choose a backup smaller than 8 MB.';restoreCandidate=null;$('#applyBackup').disabled=true;return}try{check(await file.text(),generation)}catch{$('#restoreStatus').textContent='Safari could not read that file. Try pasting its JSON instead.'}};
 $('#applyBackup').onclick=()=>{
  if(!restoreCandidate)return;try{saveChats();saveQuestionSessions();const current=makeBackup(localStorage);download('knight-school-before-restore-'+day()+'.json',JSON.stringify(current,null,2),'application/json');restoreBackup(localStorage,restoreCandidate);rehydrateTraining();$('#modal').close();toast('Backup merged. Your lessons, history and settings are ready.')}catch(e){$('#restoreStatus').textContent=e.message}
 };
}
function rehydrateTraining(){progress=JSON.parse(localStorage.getItem('knight-school-v1'))||progress;training=loadTraining(localStorage);for(const [map,key]of [[coachThreads,'knight-school-chats-v2'],[questionSessions,'knight-school-questions-v1']]){map.clear();for(const [id,v]of JSON.parse(localStorage.getItem(key)||'[]'))map.set(id,key.includes('questions')?makeQuestionState(v):v)}const theme=localStorage.getItem('knight-school-board-theme');if(theme)document.documentElement.dataset.boardTheme=theme;updateTop();if($('#lessonPanel')){renderBoard();renderPanel()}else catalogOrPage()}
document.addEventListener('click',e=>{
 const progressButton=e.target.closest('[data-training-progress]');if(progressButton){progressModal();return}
 const rating=e.target.closest('[data-recall-grade]');if(rating&&pendingRecallResult){const r=pendingRecallResult;training.reviews[reviewKey(r.lessonId,r.side)]=scheduleReview(r.previous,{lessonId:r.lessonId,side:r.side,grade:rating.dataset.recallGrade,now:r.now});persistTraining();renderPanel();return}
 const due=e.target.closest('[data-due-review]');if(due){const r=training.reviews[due.dataset.dueReview];if(!r)return;$('#modal').close();page='openings';history.replaceState(null,'','#openings');renderNav();openStudy(r.lessonId);drillSide=r.side;$('#drillSide').value=r.side;startDrill();return}
 const mistake=e.target.closest('[data-mistake-study]');if(mistake){const m=training.mistakes.find(x=>x.id===mistake.dataset.mistakeStudy);if(!m)return;$('#modal').close();pendingPracticeFen=m.fenBefore;pendingMistakeId=m.id;if(page==='practice')practice();else navigate('practice')}
});

initPWA(modal);
